#include <stdio.h>

#define INF 1000000000

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int dist[100][100];

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            dist[i][j] = (i == j) ? 0 : INF;
        }
    }

    for (int i = 0; i < M; i++) {
        int A, B, C;
        scanf("%d %d %d", &A, &B, &C);
        A--;
        B--;

        if (C < dist[A][B]) {
            dist[A][B] = C;
            dist[B][A] = C;
        }
    }

    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }

    printf("%d\n", dist[0][N - 1]);
    return 0;
}
